const CACHE='dolce-link-menu-v14';
const PAGES=['assets/link-menu/breakfast-approved.webp','assets/link-menu/breakfast-wordmark.svg','assets/link-menu/mains-wordmark.svg','assets/link-menu/mains-salads.jpeg','assets/link-menu/mains-courses.jpeg','assets/link-menu/mains-pasta.jpeg','index.html','assets/link-menu/profile.webp','assets/link-menu/drinks-wordmark-clear.webp','assets/link-menu/desserts-wordmark-clear.webp','assets/link-menu/menu-2.jpeg','assets/link-menu/menu-3.jpeg','assets/link-menu/menu-1.jpeg','assets/link-menu/dessert-with-cakes.webp','link-menu.css?v=13','link-menu.js?v=15'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(PAGES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match('index.html')));return}event.respondWith(caches.match(event.request).then(hit=>hit||fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response})))});
